import { z } from 'zod'

const name = z.string().refine((value) => value.trim() !== '', 'must not be blank')
const missingKey = 'Set LEMLIST_API_KEY or pass apiKey.'
const apiKey = z.string().optional().pipe(z.string({ error: missingKey }).trim().min(1, missingKey))

const lemlistConfigSchema = z.object({
  /** Stable checkpoint namespace for one account; use a new value when switching accounts. */
  sourceId: name,
  database: name,
  pageSize: z.int().min(1).max(100),
  start: z.date(),
  overlapMs: z.number().nonnegative(),
  intervalMs: z.int().positive(),
  /** Empty or omitted discovers all team members for the conversations stream. */
  inboxUserIds: z.array(name).readonly()
    .refine((ids) => new Set(ids).size === ids.length, 'must not repeat a user ID').optional(),
  /** Lemlist API key; read when a stream runs, never by schema commands. */
  apiKey,
})

export type LemlistConfig = z.input<typeof lemlistConfigSchema>

export const lemlistReaderConfigSchema = lemlistConfigSchema.omit({ database: true })
export type LemlistReaderConfig = z.input<typeof lemlistReaderConfigSchema>

// Storage is configured here before schema discovery.
export const lemlistConfig: LemlistConfig = {
  sourceId: 'lemlist',
  database: 'default',
  pageSize: 100,
  start: new Date('2000-01-01T00:00:00Z'),
  overlapMs: 24 * 60 * 60 * 1000,
  intervalMs: 30 * 24 * 60 * 60 * 1000,
  inboxUserIds: [],
  apiKey: process.env.LEMLIST_API_KEY,
}

import { paginate, type Page, type SourceContext, type TimestampRange } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { lemlistReaderConfigSchema, type LemlistReaderConfig } from './config.js'

export type ListResource = 'activities' | 'campaigns' | 'contacts' | 'companies'
export type InboxScope = { userId: string } | { contactId: string }
export type LemlistItem = z.infer<typeof lemlistItem>
export type LemlistSettings = Omit<z.output<typeof lemlistReaderConfigSchema>, 'apiKey'>
export interface InboxCursor { page: number; skip: number }

export interface LemlistClient {
  settings: LemlistSettings
  list(resource: ListResource, window?: TimestampRange): AsyncGenerator<Page<LemlistItem, number>>
  inbox(scope: InboxScope): AsyncGenerator<Page<LemlistItem, InboxCursor>>
  contacts(ids: readonly string[]): Promise<LemlistItem[]>
  campaignLeads(campaignId: string): Promise<LemlistItem[]>
  teamUserIds(): Promise<string[]>
}

type Get = (path: string, params: Record<string, string>) => Promise<unknown>

const nonNegative = z.int().nonnegative()
const lemlistId = z.string().refine((value) => value.trim() !== '', 'must not be blank')
const lemlistItem = z.looseObject({ _id: lemlistId })
const lemlistItems = z.array(lemlistItem)
  .refine((items) => new Set(items.map((item) => item._id)).size === items.length, 'must not repeat an object ID')
// The public API returns arrays; retain compatibility with older campaign envelopes.
const campaignItems = z.union([lemlistItems, z.looseObject({ campaigns: lemlistItems }).transform(({ campaigns }) => campaigns)])
const offsetListing = z.looseObject({ data: lemlistItems, limit: z.int().positive(), total: nonNegative, offset: nonNegative })
const inboxListing = z.looseObject({
  data: lemlistItems,
  pagination: z.looseObject({ totalItems: nonNegative, perPage: z.int().positive(), currentPage: z.int().positive(), totalPages: nonNegative, nextPage: z.int().nullable() }),
})
const team = z.looseObject({ userIds: z.array(lemlistId).optional(), users: z.array(z.looseObject({ userId: lemlistId })).optional() })

export function createLemlistClient(context: SourceContext, config: LemlistReaderConfig): LemlistClient {
  const { apiKey, ...settings } = lemlistReaderConfigSchema.parse(config)
  const authorization = `Basic ${Buffer.from(`:${apiKey}`).toString('base64')}`
  const get: Get = async (path, params) => {
    const url = new URL(`https://api.lemlist.com/api${path}`)
    for (const [name, value] of Object.entries(params)) url.searchParams.set(name, value)
    const response = await context.fetch(url, { headers: { Authorization: authorization }, redirect: 'error' })
    return response.json()
  }
  return {
    settings,
    list: (resource, window) => listPages(context, get, settings.pageSize, resource, window),
    inbox: (scope) => inboxPages(context, get, settings.pageSize, scope),
    contacts: async (ids) => {
      const items = lemlistItems.parse(await get('/contacts', { idsOrEmails: ids.join(',') }))
      const expected = new Set(ids)
      if (items.length !== ids.length || items.some((item) => !expected.has(item._id))) {
        throw new Error('Lemlist contact lookup did not return every discovered contact; replay this stream.')
      }
      return items
    },
    // The normal lead list has a 500-row cap and no continuation. This endpoint explicitly exports all states.
    campaignLeads: async (campaignId) => lemlistItems.parse(
      await get(`/v2/campaigns/${encodeURIComponent(campaignId)}/export/leads`, { state: 'all', format: 'json' }),
    ),
    teamUserIds: async () => {
      const members = team.parse(await get('/team', { version: 'v2' }))
      const ids = members.userIds ?? members.users?.map((user) => user.userId)
      if (!ids?.length) throw new Error('Lemlist team has no member IDs; configure inboxUserIds or restore team access.')
      return [...new Set(ids)]
    },
  }
}

/** Offsets are local traversal positions, never durable change cursors. */
function listPages(context: SourceContext, get: Get, pageSize: number, resource: ListResource, window: TimestampRange | undefined) {
  const seen = new Set<string>()
  return paginate({
    context, initial: 0, label: `GET /${resource}`,
    fetchPage: async (offset = 0) => {
      const params: Record<string, string> = { limit: String(pageSize), offset: String(offset) }
      if (resource === 'activities' || resource === 'campaigns') params.version = 'v2'
      if (window) {
        params.minDate = window.from.toISOString()
        params.maxDate = window.to.toISOString()
      } else if (resource !== 'contacts') {
        params.sortBy = 'createdAt'
        params.sortOrder = 'asc'
      }
      const result = await get(`/${resource}`, params)
      let items: LemlistItem[]
      let next: number | undefined
      if (resource === 'contacts' || resource === 'companies') {
        const listing = offsetListing.parse(result)
        items = listing.data
        if (listing.offset !== offset || listing.limit > pageSize || items.length > listing.limit ||
          offset + items.length > listing.total || (items.length < listing.limit && offset + items.length < listing.total)) {
          throw new Error(`Lemlist ${resource} has inconsistent pagination; replay this stream.`)
        }
        next = offset + items.length < listing.total ? offset + listing.limit : undefined
      } else {
        items = resource === 'campaigns' ? campaignItems.parse(result) : lemlistItems.parse(result)
        if (items.length > pageSize) throw new Error(`Lemlist ${resource} exceeds pageSize.`)
        next = items.length === pageSize ? offset + items.length : undefined
      }
      rejectRepeatedPage(items, seen, resource)
      if (next !== undefined && !Number.isSafeInteger(next)) throw new Error('Lemlist offset exceeded the safe integer range.')
      return { items, next }
    },
  })
}

/** Inbox pagination is page-based; the messages endpoint accepts the equivalent skip. */
function inboxPages(context: SourceContext, get: Get, pageSize: number, scope: InboxScope) {
  const path = 'userId' in scope ? '/inbox' : `/inbox/${encodeURIComponent(scope.contactId)}`
  const seen = new Set<string>()
  let expectedTotal: number | undefined
  let received = 0
  return paginate({
    context, initial: { page: 1, skip: 0 }, label: `GET ${path}`,
    fetchPage: async (cursor: InboxCursor = { page: 1, skip: 0 }) => {
      const params: Record<string, string> = { limit: String(pageSize) }
      if ('userId' in scope) {
        params.userId = scope.userId
        params.page = String(cursor.page)
      } else {
        params.skip = String(cursor.skip)
        params.markAsRead = 'false'
      }
      const { data: items, pagination } = inboxListing.parse(await get(path, params))
      const { totalItems: total, perPage, currentPage, totalPages, nextPage } = pagination
      if (currentPage !== cursor.page || perPage > pageSize || items.length > perPage ||
        (expectedTotal !== undefined && total !== expectedTotal) ||
        (nextPage !== null && (nextPage !== currentPage + 1 || items.length === 0 || currentPage >= totalPages)) ||
        (nextPage === null && totalPages > currentPage)) {
        throw new Error('Lemlist inbox has malformed or incomplete pagination; replay this stream.')
      }
      rejectRepeatedPage(items, seen, path)
      const count = received + items.length
      if (count > total || (nextPage === null && count !== total)) throw new Error('Lemlist inbox ended before its advertised complete collection.')
      expectedTotal = total
      received = count
      const next = nextPage === null ? undefined : { page: nextPage, skip: cursor.skip + perPage }
      return { items, next }
    },
  })
}

function rejectRepeatedPage(items: readonly LemlistItem[], seen: Set<string>, label: string) {
  if (items.some((item) => seen.has(item._id))) throw new Error(`Lemlist ${label} repeated a page or object ID; replay this stream.`)
  for (const item of items) seen.add(item._id)
}

import { definePipeline, defineStream, fullSync } from '@chkit/plugin-ingest'

import { lemlistConfig, type LemlistReaderConfig } from './config.js'
import { createActivityWindow, lemlist_activitiesRaw, readActivities } from './sources/activities.js'
import { lemlist_campaignsRaw, readCampaigns } from './sources/campaigns.js'
import { lemlist_contactsRaw, readContacts } from './sources/contacts.js'
import { lemlist_companiesRaw, readCompanies } from './sources/companies.js'
import { lemlist_campaignLeadsRaw, readCampaignLeads } from './sources/campaign-leads.js'
import { lemlist_inboxConversationsRaw, readInboxConversations } from './sources/inbox-conversations.js'
import { lemlist_inboxMessagesRaw, readInboxMessages } from './sources/inbox-messages.js'

/** One account pipeline; every resource owns its discovery and checkpoint. */
export function createLemlistPipeline(config: LemlistReaderConfig = lemlistConfig) {
  const boundConfig = { ...config, start: new Date(config.start), inboxUserIds: config.inboxUserIds ? [...config.inboxUserIds] : undefined }
  return definePipeline({
    id: boundConfig.sourceId, tags: ['provider:lemlist'], maxStreams: 1, maxFetches: 1,
    streams: [
      defineStream({
        id: `${boundConfig.sourceId}.activities`, tags: ['resource:activities'], destination: lemlist_activitiesRaw,
        incremental: createActivityWindow(boundConfig), batchSize: 500,
        read: (context) => readActivities(context, boundConfig),
      }),
      defineStream({
        id: `${boundConfig.sourceId}.campaigns`, tags: ['resource:campaigns'], destination: lemlist_campaignsRaw,
        incremental: fullSync(),
        read: (context) => readCampaigns(context, boundConfig),
      }),
      defineStream({ id: `${boundConfig.sourceId}.contacts`, tags: ['resource:contacts'], destination: lemlist_contactsRaw,
        incremental: fullSync(), read: (context) => readContacts(context, boundConfig) }),
      defineStream({ id: `${boundConfig.sourceId}.companies`, tags: ['resource:companies'], destination: lemlist_companiesRaw,
        incremental: fullSync(), read: (context) => readCompanies(context, boundConfig) }),
      defineStream({ id: `${boundConfig.sourceId}.campaign_leads`, tags: ['resource:campaign_leads'], destination: lemlist_campaignLeadsRaw,
        incremental: fullSync(), read: (context) => readCampaignLeads(context, boundConfig) }),
      defineStream({ id: `${boundConfig.sourceId}.inbox_conversations`, tags: ['resource:inbox_conversations'], destination: lemlist_inboxConversationsRaw,
        incremental: fullSync(), read: (context) => readInboxConversations(context, boundConfig) }),
      defineStream({ id: `${boundConfig.sourceId}.inbox_messages`, tags: ['resource:inbox_messages'], destination: lemlist_inboxMessagesRaw,
        incremental: fullSync(), read: (context) => readInboxMessages(context, boundConfig) }),
    ],
  })
}

export const lemlistPipeline = createLemlistPipeline()

import { rawRows, rawTable, timestampWindow, type IncrementalStrategy, type ReadContext, type TimestampRange, type TimestampWindowState } from '@chkit/plugin-ingest'

import { createLemlistClient } from '../client.js'
import { lemlistConfig, type LemlistReaderConfig } from '../config.js'

export const lemlist_activitiesRaw = rawTable({ database: lemlistConfig.database, name: 'lemlist_activities_raw' })

export async function* readActivities(context: ReadContext<TimestampRange, TimestampWindowState>, config: LemlistReaderConfig) {
  const client = createLemlistClient(context, config)
  for (let from = context.selection.from; from < context.selection.to;) {
    const to = new Date(Math.min(from.getTime() + client.settings.intervalMs, context.selection.to.getTime()))
    for await (const page of client.list('activities', { from, to })) {
      yield { rows: rawRows(page.items, (item) => item._id) }
    }
    // Only an exhausted interval is a safe frontier. Its mutable offsets restart at zero.
    const watermark = new Date(Math.max(to.getTime(), Date.parse(context.state?.watermark ?? to.toISOString()))).toISOString()
    yield { rows: [], state: { watermark }, id: `completed-interval:${from.toISOString()}/${to.toISOString()}` }
    from = to
  }
}

export function createActivityWindow(config: LemlistReaderConfig): IncrementalStrategy<TimestampWindowState, TimestampRange> {
  const window = timestampWindow({ start: config.start, overlapMs: config.overlapMs })
  return {
    ...window,
    plan(input: Parameters<typeof window.plan>[0]) {
      const selection = window.plan(input)
      if (input.range && input.state) {
        const frontier = Date.parse(input.state.watermark)
        if (selection.to.getTime() < frontier) {
          throw new Error('Lemlist backfill upper bound precedes its committed interval frontier; use a new backfill ID for a narrower historical range.')
        }
        return { ...selection, from: new Date(Math.max(selection.from.getTime(), frontier - config.overlapMs)) }
      }
      return selection
    },
  }
}

import { rawRows, rawTable, type SourceContext } from '@chkit/plugin-ingest'

import { createLemlistClient } from '../client.js'
import { lemlistConfig, type LemlistReaderConfig } from '../config.js'

export const lemlist_campaignsRaw = rawTable({ database: lemlistConfig.database, name: 'lemlist_campaigns_raw' })

// No reliable modification filter: default fullSync records completion and safely replays failures.
export async function* readCampaigns(context: SourceContext, config: LemlistReaderConfig) {
  const client = createLemlistClient(context, config)
  for await (const page of client.list('campaigns')) {
    yield { rows: rawRows(page.items, (item) => item._id) }
  }
}

import { expect, test } from 'bun:test'
import { runIngestion, selectStreams, type PipelineDefinition } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { lemlistConfig } from '../config.js'
import { createLemlistPipeline } from '../index.js'

const fixtureConfig = { ...lemlistConfig, apiKey: 'fixture' }
const cutoff = new Date('2000-03-01T00:00:00Z')
const retry = { retries: 0 }

test('Lemlist commits only exhausted date intervals and replays the unfinished interval with overlap', async () => {
  let fail = true
  const journal = createMemoryJournal()
  let acknowledgeInterval = () => {}
  const intervalCommitted = new Promise<void>((resolve) => { acknowledgeInterval = resolve })
  const append = journal.append
  journal.append = async (events) => {
    await append(events)
    if (events.some((event) => JSON.stringify(event.checkpoint?.state) === '{"watermark":"2000-01-31T00:00:00.000Z"}')) acknowledgeInterval()
  }
  const windows: { from: string | null; to: string | null; offset: string | null }[] = []
  const env = lemlistEnv(async (url) => {
    const from = url.searchParams.get('minDate')
    windows.push({ from, to: url.searchParams.get('maxDate'), offset: url.searchParams.get('offset') })
    if (fail && from !== '2000-01-01T00:00:00.000Z') {
      await intervalCommitted
      return new Response('denied', { status: 403 })
    }
    return Response.json([{ _id: from, custom: { retained: true } }])
  })
  const destination = createMemoryDestination()
  const request = { selected: selected(), backfill: undefined }
  expect((await runIngestion(request, { ...env, journal, destination, now: () => cutoff, retry })).ok).toBe(false)
  expect((await journal.readCheckpoint('lemlist.activities')).envelope?.state).toEqual({ watermark: '2000-01-31T00:00:00.000Z' })
  expect(destination.tables.get('default.lemlist_activities_raw')?.[0]?.raw).toMatchObject({ custom: { retained: true } })
  fail = false
  expect((await runIngestion(request, { ...env, journal, destination, now: () => cutoff, retry })).ok).toBe(true)
  expect(windows[2]).toEqual({ from: '2000-01-30T00:00:00.000Z', to: '2000-02-29T00:00:00.000Z', offset: '0' })
  expect((await journal.readCheckpoint('lemlist.activities')).envelope?.state).toEqual({ watermark: cutoff.toISOString() })
})

test('Lemlist resumes isolated explicit backfills from the completed interval frontier', async () => {
  let fail = true
  const starts: string[] = []
  const env = lemlistEnv(async (url) => {
    const from = url.searchParams.get('minDate') ?? ''
    starts.push(from)
    if (fail && from !== '2025-01-01T00:00:00.000Z') return new Response('denied', { status: 403 })
    return Response.json([])
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected(), backfill: { id: 'history', from: new Date('2025-01-01T00:00:00Z'), to: new Date('2025-03-01T00:00:00Z') } }
  expect((await runIngestion(request, { ...env, journal, destination, now: () => new Date('2026-01-01'), retry })).ok).toBe(false)
  expect((await journal.readCheckpoint('lemlist.activities#backfill:history')).envelope?.state).toEqual({ watermark: '2025-01-31T00:00:00.000Z' })
  fail = false
  expect((await runIngestion(request, { ...env, journal, destination, now: () => new Date('2026-01-01'), retry })).ok).toBe(true)
  expect(starts[2]).toBe('2025-01-30T00:00:00.000Z')
  expect((await journal.readCheckpoint('lemlist.activities')).envelope).toBeUndefined()
})

test('Lemlist rejects a narrowed completed backfill upper bound without regressing its frontier', async () => {
  let requests = 0
  const env = lemlistEnv(async () => { requests++; return Response.json([]) })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const backfill = { id: 'narrowed', from: new Date('2025-01-01T00:00:00Z'), to: new Date('2025-03-01T00:00:00Z') }
  const request = { selected: selected(), backfill }
  expect((await runIngestion(request, { ...env, journal, destination, now: () => new Date('2026-01-01'), retry })).ok).toBe(true)
  const completedRequests = requests
  // This upper bound is still after the overlap's lower bound, but must not move the watermark backwards.
  const result = await runIngestion({ ...request, backfill: { ...backfill, to: new Date('2025-02-28T12:00:00Z') } }, {
    ...env, journal, destination, now: () => new Date('2026-01-01'), retry,
  })
  expect(result.ok).toBe(false)
  expect(result.streams[0]?.error).toContain('use a new backfill ID')
  expect(requests).toBe(completedRequests)
  expect((await journal.readCheckpoint('lemlist.activities#backfill:narrowed')).envelope?.state).toEqual({ watermark: '2025-03-01T00:00:00.000Z' })
})

test('Lemlist paginates a whole date interval and a rejected sink cannot advance it', async () => {
  const offsets: string[] = []
  const env = lemlistEnv(async (url) => {
    offsets.push(url.searchParams.get('offset') ?? '')
    expect(url.searchParams.get('minDate')).toBe('2000-01-01T00:00:00.000Z')
    expect(url.searchParams.get('maxDate')).toBe('2000-01-02T00:00:00.000Z')
    return Response.json(url.searchParams.get('offset') === '0' ? Array.from({ length: 100 }, (_, index) => ({ _id: String(index) })) : [{ _id: 'last' }])
  })
  const journal = createMemoryJournal()
  const request = { selected: selected(), backfill: undefined }
  const result = await runIngestion(request, { ...env, journal, destination: { insert: async () => { throw new Error('sink rejected') } }, now: () => new Date('2000-01-02'), retry })
  expect(result.ok).toBe(false)
  expect((await journal.readCheckpoint('lemlist.activities')).envelope).toBeUndefined()
  expect(offsets).toEqual(['0', '100'])
})

test('Lemlist empty activity intervals commit and campaigns always scan from zero', async () => {
  const paths: URL[] = []
  const env = lemlistEnv(async (url) => { paths.push(url); return Response.json({ campaigns: [] }) })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected('campaigns'), backfill: undefined }
  expect((await runIngestion(request, { ...env, journal, destination, now: () => cutoff, retry })).ok).toBe(true)
  expect((await runIngestion(request, { ...env, journal, destination, now: () => new Date('2000-03-02'), retry })).ok).toBe(true)
  expect(paths.map((url) => url.searchParams.get('offset'))).toEqual(['0', '0'])
  expect(paths.every((url) => url.searchParams.get('sortBy') === 'createdAt' && url.searchParams.get('sortOrder') === 'asc')).toBe(true)
  expect((await journal.readCheckpoint('lemlist.campaigns')).lastSuccessSeq).toBeGreaterThan(0)
  expect(journal.events.filter((event) => event.namespaceId === 'lemlist.campaigns' && event.eventKind === 'work_finished' && event.workState === 'succeeded')).toHaveLength(2)
  const empty = lemlistEnv(async () => Response.json([]))
  expect((await runIngestion({ selected: selected(), backfill: undefined }, { ...empty, journal, destination, now: () => cutoff, retry })).ok).toBe(true)
  expect((await journal.readCheckpoint('lemlist.activities')).envelope?.state).toEqual({ watermark: cutoff.toISOString() })
})

test('Lemlist binds account configuration and its API key to independent resource streams and preserves activity progress after a campaign failure', async () => {
  const config = { ...fixtureConfig, sourceId: 'lemlist.sales', pageSize: 2, start: new Date('2026-01-01'), overlapMs: 0, intervalMs: 24 * 60 * 60 * 1000, apiKey: 'sales-key' }
  const urls: URL[] = []
  let campaignsAvailable = false
  const env = lemlistEnv((url, init) => {
    urls.push(url)
    expect(init?.headers).toEqual({ Authorization: `Basic ${Buffer.from(':sales-key').toString('base64')}` })
    if (url.pathname.endsWith('/campaigns')) return campaignsAvailable ? Response.json({ campaigns: [] }) : new Response('denied', { status: 403 })
    return Response.json(url.searchParams.get('offset') === '0' ? [{ _id: 'a' }, { _id: 'b' }] : [{ _id: 'c', custom: true }])
  })
  const pipeline = createLemlistPipeline(config)
  config.pageSize = 100
  config.start.setUTCFullYear(2000)
  config.apiKey = 'changed'
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const selected = selectStreams([pipeline], []).filter((item) => ['lemlist.sales.activities', 'lemlist.sales.campaigns'].includes(item.stream.id))
  const result = await runIngestion({ selected, backfill: undefined }, { ...env, journal, destination, now: () => new Date('2026-01-02'), retry })
  expect(result.streams.map((stream) => [stream.streamId, stream.outcome])).toEqual([
    ['lemlist.sales.activities', 'succeeded'], ['lemlist.sales.campaigns', 'failed'],
  ])
  expect((await journal.readCheckpoint('lemlist.sales.activities')).envelope?.state).toEqual({ watermark: '2026-01-02T00:00:00.000Z' })
  expect((await journal.readCheckpoint('lemlist.sales.campaigns')).lastSuccessSeq).toBe(0)
  expect(urls.filter((url) => url.pathname.endsWith('/activities')).map((url) => [url.searchParams.get('minDate'), url.searchParams.get('offset'), url.searchParams.get('limit')])).toEqual([
    ['2026-01-01T00:00:00.000Z', '0', '2'], ['2026-01-01T00:00:00.000Z', '2', '2'],
  ])
  expect(destination.tables.get('default.lemlist_activities_raw')?.map((row) => row.id)).toEqual(['a', 'b', 'c'])
  campaignsAvailable = true
  urls.length = 0
  expect((await runIngestion({ selected: selectStreams([pipeline], ['resource:campaigns']), backfill: undefined }, { ...env, journal, destination })).ok).toBe(true)
  expect(urls.map((url) => url.pathname)).toEqual(['/api/campaigns'])
  expect((await journal.readCheckpoint('lemlist.sales.campaigns')).lastSuccessSeq).toBeGreaterThan(0)
  expect((await journal.readCheckpoint('lemlist.activities')).envelope).toBeUndefined()
})

test('Lemlist rejects repeated offset payloads without recording full-scan completion', async () => {
  const offsets: string[] = []
  const env = lemlistEnv((url) => {
    offsets.push(url.searchParams.get('offset') ?? '')
    return Response.json({ campaigns: [{ _id: 'repeated' }] })
  })
  const pipeline = createLemlistPipeline({ ...fixtureConfig, pageSize: 1 })
  const journal = createMemoryJournal()
  const result = await runIngestion({ selected: selectStreams([pipeline], ['resource:campaigns']), backfill: undefined }, { ...env, journal, destination: createMemoryDestination() })
  expect(result.ok).toBe(false)
  expect(result.streams[0]?.error).toContain('repeated a page')
  expect(offsets).toEqual(['0', '1'])
